WITH account_totals AS (SELECT account_id, SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END) AS debit_count, MAX(txn_time) AS last_txn_time FROM transactions GROUP BY account_id) SELECT accounts.id, accounts.opened_date, accounts.customer_id, account_totals.debit_count, account_totals.last_txn_time FROM accounts JOIN account_totals ON accounts.id = account_totals.account_id WHERE account_totals.debit_count > 51 ORDER BY customer_id DESC
